class Solution { public int findLUSlength(String[] strs){Arrays.sort(strs,(a,b)->a.length()!=b.length()?Integer.compare(b.length(),a.length()):a.compareTo(b));for(int i=0;i<strs.length;i++){boolean uncommon=true;for(int j=0;j<strs.length&&uncommon;j++)if(i!=j&&isSubsequence(strs[i],strs[j]))uncommon=false;if(uncommon)return strs[i].length();}return -1;}private boolean isSubsequence(String small,String large){int index=0;for(int i=0;i<large.length()&&index<small.length();i++)if(small.charAt(index)==large.charAt(i))index++;return index==small.length();} }
